ValidationRule.errorConditionFormula:
AND(
    /* Solo validar si los tres campos tienen valor */
    NOT(ISBLANK(ELM_Fecha_inicio__c)),
    NOT(ISBLANK(Fecha_de_L_Base__c)),
    NOT(ISBLANK(Fecha_de_cierre_proyectada__c)),

    /* La condición de error: Si la secuencia NO es correcta */
    OR(
        ELM_Fecha_inicio__c >= Fecha_de_L_Base__c,
        Fecha_de_L_Base__c >= Fecha_de_cierre_proyectada__c
    )
)
